import { get, handleApiError, post } from '@helpers/httpClient';

import { IMedicament, IMedicamentCategory, IMedicamentForm } from '../@types/medicaments.types';
import {
  mapMedicamentsCategoriesToFront,
  mapMedicamentsFormToFront,
  mapMedicamentsToFront,
  mapMedicamentToAddDTO,
  mapMedicamentToUpdateDTO,
} from '../mappers/medicaments.mapper';

export const getMedicamentsAsync = async () => {
  const rawData = await get('/ajax/medicaments/medicament_list.php').then<any>(handleApiError);
  return rawData.map(mapMedicamentsToFront) as IMedicament[];
};

export const addMedicamentAsync = async (m: Omit<IMedicament, 'id'>): Promise<IMedicament> => {
  const { id } = await post(
    '/ajax/medicaments/medicament_add.php',
    mapMedicamentToAddDTO(m),
  ).then<any>(handleApiError);
  return {
    ...m,
    id,
  };
};

export const editMedicamentAsync = async (m: IMedicament): Promise<IMedicament> => {
  await post('/ajax/medicaments/medicament_edit.php', mapMedicamentToUpdateDTO(m)).then(
    handleApiError,
  );
  return m;
};

export const getMedicamentsCategoriesAsync = async () => {
  const rawData = await get('/ajax/medicaments/medicament_categories_list.php');
  return rawData.map(mapMedicamentsCategoriesToFront);
};

export const getMedicamentsFormsAsync = async () => {
  const rawData = await get('/ajax/medicaments/medicament_forms_list.php');
  return rawData.map(mapMedicamentsFormToFront);
};

export const addMedicamentsCategoryAsync = async (name: string): Promise<IMedicamentCategory> => {
  const rawData = await post('/ajax/medicaments/medicament_categories_add.php', { name });
  return {
    id: +rawData.id,
    name,
  };
};

export const addMedicamentsFormAsync = async (name: string): Promise<IMedicamentForm> => {
  const rawData = await post('/ajax/medicaments/medicament_forms_add.php', { name });
  return {
    id: +rawData.id,
    name,
  };
};
